import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused Tanh + HardSwish + Residual Add
// out[i] = x_conv[i] + HardSwish(tanh(x_norm[i]))
// HardSwish(x) = x * ReLU6(x + 3) / 6
// ReLU6(x) = min(max(x, 0), 6)
__global__ void fused_tanh_hardswish_res_kernel(
    const float* __restrict__ x_conv,
    const float* __restrict__ x_norm,
    float* __restrict__ out,
    int total_elems
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elems) {
        float val_norm = x_norm[idx];
        float t = tanhf(val_norm);
        float hs_in = t + 3.0f;
        float relu6 = hs_in < 0.0f ? 0.0f : (hs_in > 6.0f ? 6.0f : hs_in);
        float hs = t * (relu6 / 6.0f);
        out[idx] = x_conv[idx] + hs;
    }
}

// Fused Tanh + HardSwish + Residual Add (host function)
torch::Tensor fused_tanh_hardswish_res_cuda(
    torch::Tensor x_conv,
    torch::Tensor x_norm
) {
    auto out = torch::empty_like(x_conv);
    int total_elems = x_conv.numel();
    int threads = 256;
    int blocks = (total_elems + threads - 1) / threads;
    fused_tanh_hardswish_res_kernel<<<blocks, threads>>>(
        x_conv.data_ptr<float>(),
        x_norm.data_ptr<float>(),
        out.data_ptr<float>(),
        total_elems
    );
    return out;
}

// LogSumExp across dim=1, keepdim=True
// Input shape: (N, C, H, W), Output shape: (N, 1, H, W)
__global__ void fused_logsumexp_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int N, int C, int H, int W
) {
    // Each thread handles one (n, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * H * W) {
        int n = idx / (H * W);
        int hw = idx % (H * W);
        int h = hw / W;
        int w = hw % W;

        // Compute logsumexp over channel dimension
        // We do a naive approach: find max, then sum
        float max_val = -1e30f;
        int base_idx = ((n * C) * H + h) * W + w;
        // first pass: find max
        for(int c = 0; c < C; c++){
            float val = inp[base_idx + c * H * W];
            if(val > max_val) {
                max_val = val;
            }
        }
        // second pass: sum
        float sum_val = 0.0f;
        for(int c = 0; c < C; c++){
            float val = inp[base_idx + c * H * W];
            sum_val += expf(val - max_val);
        }
        // log of sum plus max
        float lse = logf(sum_val) + max_val;
        out[((n * 1) * H + h) * W + w] = lse;
    }
}

// LogSumExp across dim=1 (host function)
torch::Tensor fused_logsumexp_cuda(torch::Tensor inp) {
    auto sizes = inp.sizes();
    int N = sizes[0];
    int C = sizes[1];
    int H = sizes[2];
    int W = sizes[3];

    // output shape: (N, 1, H, W)
    auto out = torch::empty({N, 1, H, W}, inp.options());
    int total_threads = N * H * W;
    int threads = 256;
    int blocks = (total_threads + threads - 1) / threads;
    fused_logsumexp_kernel<<<blocks, threads>>>(
        inp.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W
    );
    return out;
}

"""

fused_ops_cpp_source = r"""
torch::Tensor fused_tanh_hardswish_res_cuda(torch::Tensor x_conv, torch::Tensor x_norm);
torch::Tensor fused_logsumexp_cuda(torch::Tensor inp);
"""

# Build our custom fused ops
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_tanh_hardswish_res_cuda", "fused_logsumexp_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model using custom CUDA kernels to fuse Tanh, HardSwish, Residual Addition,
    and LogSumExp.
    """
    def __init__(self, in_channels, out_channels, kernel_size, groups, eps=1e-5):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(groups, out_channels, eps=eps)

    def forward(self, x):
        # Convolution
        x_conv = self.conv(x)
        # Group Normalization
        x_norm = self.group_norm(x_conv)
        # Fused Tanh + HardSwish + Residual
        x_fused = fused_ops.fused_tanh_hardswish_res_cuda(x_conv, x_norm)
        # LogSumExp along channel dimension
        x_out = fused_ops.fused_logsumexp_cuda(x_fused)
        return x_out
